/***************************************************************************************************** 
 *
 * 
 * An image is represented by a 2-D array of integers, each integer representing the pixel value of 
 * the image (from 0 to 65535).
 * 
 * Given a coordinate (sr, sc) representing the starting pixel (row and column) of the flood fill, and 
 * a pixel value newColor, "flood fill" the image.
 * 
 * To perform a "flood fill", consider the starting pixel, plus any pixels connected 4-directionally 
 * to the starting pixel of the same color as the starting pixel, plus any pixels connected 
 * 4-directionally to those pixels (also with the same color as the starting pixel), and so on.  
 * Replace the color of all of the aforementioned pixels with the newColor.
 * 
 * At the end, return the modified image.
 * 
 * Example 1:
 * 
 * Input: 
 * image = [[1,1,1],[1,1,0],[1,0,1]]
 * sr = 1, sc = 1, newColor = 2
 * Output: [[2,2,2],[2,2,0],[2,0,1]]
 * Explanation: 
 * From the center of the image (with position (sr, sc) = (1, 1)), all pixels connected 
 * by a path of the same color as the starting pixel are colored with the new color.
 * Note the bottom corner is not colored 2, because it is not 4-directionally connected
 * to the starting pixel.
 * 
 * Note:
 * The length of image and image[0] will be in the range [1, 50].
 * The given starting pixel will satisfy 0  and 0 .
 * The value of each color in image[i][j] and newColor will be an integer in [0, 65535].
 ******************************************************************************************************/

class Solution {
    public int[][] floodFill(int[][] image, int sr, int sc, int newColor) {
        if (image == null || image[sr][sc] == newColor) {
            return image;
        }

        dfs(image, sr, sc, image[sr][sc], newColor);
        return image;
    }

    void dfs(int[][] image, int sr, int sc, int originalColor, int newColor) {
        image[sr][sc] = newColor;

        var dx = new int[] {0, 0, 1, -1};
        var dy = new int[] {1, -1, 0, 0};
        for (var i = 0; i < 4; i++) {
            var x = sr + dx[i];
            var y = sc + dy[i];
            if (x >= 0 && x < image.length && y >= 0 && y < image[0].length
               && image[x][y] == originalColor) {
                dfs(image, x, y, originalColor, newColor);
            }
        }
    }
}

class Solution {
public:
    vector<vector<int>> floodFill(vector<vector<int>>& image, int sr, int sc, int newColour) {
        int rowSize = image.size();
        int colSize = image[0].size();
        int prevColour = image[sr][sc];
        vector<vector<int>> visited(rowSize, vector<int>(colSize, 0));
        queue<pair<int, int>> pixelToColour;
        pixelToColour.push(make_pair(sr, sc));
        while(pixelToColour.size() > 0) {
            int r = pixelToColour.front().first;
            int c = pixelToColour.front().second;
            image[r][c] = newColour;
            visited[r][c] = 1;
            if (r > 0) {
                if (image[r-1][c] == prevColour and !visited[r-1][c]) {
                    pixelToColour.push(make_pair(r-1, c));
                }
            }
            if (r < rowSize - 1) {
                if (image[r+1][c] == prevColour and !visited[r+1][c]) {
                    pixelToColour.push(make_pair(r+1, c));
                }
            }
            if (c > 0) {
                if (image[r][c-1] == prevColour and !visited[r][c-1]) {
                    pixelToColour.push(make_pair(r, c-1));
                }
            }
            if (c < colSize  - 1) {
                if (image[r][c+1] == prevColour and !visited[r][c+1]) {
                    pixelToColour.push(make_pair(r, c+1));
                }
            }
            pixelToColour.pop();
        }
        return image;
    }
};

class Solution {
    public int[][] floodFill(int[][] image, int sr, int sc, int newColor) {
        int color = image[sr][sc];
        if (color != newColor) dfs(image, sr, sc, color, newColor);
        return image;
    }
    public void dfs(int[][] image, int r, int c, int color, int newColor) {
        if (image[r][c] == color) {
            image[r][c] = newColor;
            if (r >= 1) dfs(image, r-1, c, color, newColor);
            if (c >= 1) dfs(image, r, c-1, color, newColor);
            if (r+1 < image.length) dfs(image, r+1, c, color, newColor);
            if (c+1 < image[0].length) dfs(image, r, c+1, color, newColor);
        }
    }
}

class Solution(object):
    def floodFill(self, image, sr, sc, newColor):
        R, C = len(image), len(image[0])
        color = image[sr][sc]
        if color == newColor: return image
        def dfs(r, c):
            if image[r][c] == color:
                image[r][c] = newColor
                if r >= 1: dfs(r-1, c)
                if r+1 < R: dfs(r+1, c)
                if c >= 1: dfs(r, c-1)
                if c+1 < C: dfs(r, c+1)

        dfs(sr, sc)
        return image

